// Captura todo o payload e retorna para debug
const item = $input.first().json;

const debug = {
  received_keys: Object.keys(item),
  has_body: !!item.body,
  has_sender: !!item.body?.sender,
  has_data: !!item.body?.data,
  sender_raw: item.body?.sender || 'NOT_FOUND',
  message_type: item.body?.data?.messageType || 'NOT_FOUND',
  message_text: item.body?.data?.message?.conversation || 'NOT_FOUND',
  pushName: item.body?.data?.pushName || 'NOT_FOUND',
  full_payload: item
};

return [{ json: debug }];
